namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;
    private int _nextId;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals and salads", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and bakes", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Quick bites and appetizers", Icon = "🍿" },
            new() { Name = "Drinks", Description = "Smoothies, cocktails, and more", Icon = "🥤" }
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients until just mixed.\n4. Heat a greased pan over medium heat.\n5. Pour batter and cook until bubbles form, then flip.\n6. Serve with maple syrup and fresh berries.",
                AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan cheese\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop the romaine lettuce.\n2. Toss with Caesar dressing.\n3. Top with croutons and shaved parmesan.\n4. Add grilled chicken if desired.\n5. Serve immediately.",
                AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = "400g spaghetti\n500g ground beef\n1 onion, diced\n2 cloves garlic\n400g canned tomatoes\n2 tbsp tomato paste\nFresh basil\nOlive oil",
                Steps = "1. Cook spaghetti according to package directions.\n2. Sauté onion and garlic in olive oil.\n3. Add ground beef and brown thoroughly.\n4. Stir in tomatoes and tomato paste.\n5. Simmer for 20 minutes.\n6. Serve sauce over spaghetti with fresh basil.",
                AverageRating = 4.8, RatingCount = 25 },
            new() { Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = "200g dark chocolate\n100g butter\n3 eggs\n100g sugar\n50g flour",
                Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold in chocolate mixture and flour.\n4. Pour into greased ramekins.\n5. Bake at 200°C for 12 minutes.\n6. Invert onto plates and serve immediately.",
                AverageRating = 4.9, RatingCount = 30 },
            new() { Id = 5, Title = "Guacamole", Category = "Snacks",
                Ingredients = "3 ripe avocados\n1 lime, juiced\n1 tsp salt\n1/2 cup onion, diced\n3 tbsp fresh cilantro\n2 roma tomatoes, diced\n1 tsp garlic, minced",
                Steps = "1. Cut avocados in half and remove pit.\n2. Mash avocado in a bowl.\n3. Stir in lime juice and salt.\n4. Mix in onion, cilantro, tomatoes, and garlic.\n5. Serve with tortilla chips.",
                AverageRating = 4.3, RatingCount = 15 },
            new() { Id = 6, Title = "Mango Smoothie", Category = "Drinks",
                Ingredients = "1 cup frozen mango\n1 banana\n1 cup yogurt\n1/2 cup orange juice\n1 tbsp honey",
                Steps = "1. Add all ingredients to a blender.\n2. Blend until smooth.\n3. Pour into a glass and serve immediately.",
                AverageRating = 4.1, RatingCount = 6 }
        };

        _nextId = 7;
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}

