arguments.file_text:
@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">@($"{Rating:F1}") ⭐ (@Count ratings)</span>
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _hoveredStar ? "hovered" : "") @(star <= _selectedStar ? "selected" : "")"
                  @onmouseover="() => _hoveredStar = star"
                  @onmouseout="() => _hoveredStar = 0"
                  @onclick="() => SubmitRating(star)">★</span>
        }
    </div>
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

<style>
    .star-rating { margin: 1rem 0; }
    .rating-label { font-size: 0.9rem; color: #666; }
    .stars { display: inline-flex; gap: 0.2rem; cursor: pointer; font-size: 1.8rem; }
    .star { color: #ddd; transition: color 0.15s; }
    .star.hovered, .star.selected { color: #f5a623; }
    .rating-thanks { display: block; color: green; margin-top: 0.3rem; font-size: 0.85rem; }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double Rating { get; set; }
    [Parameter] public int Count { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _hoveredStar;
    private int _selectedStar;
    private bool _submitted;

    private async Task SubmitRating(int stars)
    {
        _selectedStar = stars;
        _submitted = true;
        await OnRated.InvokeAsync(stars);
    }
}

@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

<div class="container">
    <div class="hero text-center py-5">
        <h1>🍳 Recipe Community</h1>
        <p class="lead">Discover, share, and rate delicious recipes from our community</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row">
        @foreach (var category in _categories)
        {
            <div class="col-md-4 mb-4">
                <a href="/category/@category.Name" class="text-decoration-none">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body text-center">
                            <span style="font-size: 3rem;">@category.Icon</span>
                            <h3 class="card-title mt-2">@category.Name</h3>
                            <p class="card-text text-muted">@category.Description</p>
                        </div>
                    </div>
                </a>
            </div>
        }
    </div>
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<RecipeCommunity.Models.RecipeCategory> _categories = new();

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }
}

@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (_recipes.Count == 0)
    {
        <p class="text-muted">No recipes in this category yet. <a href="/submit">Be the first to add one!</a></p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in _recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">
                                <a href="/recipe/@recipe.Id">@recipe.Title</a>
                            </h4>
                            <p class="text-muted mb-1">
                                ⭐ @($"{recipe.AverageRating:F1}") (@recipe.RatingCount ratings)
                            </p>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<Recipe> _recipes = new();

    protected override void OnInitialized()
    {
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe")</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (_recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@_recipe.Category">@_recipe.Category</a></li>
                <li class="breadcrumb-item active">@_recipe.Title</li>
            }
        </ol>
    </nav>

    @if (_recipe is null)
    {
        <p>Recipe not found.</p>
    }
    else
    {
        <h1>@_recipe.Title</h1>

        <StarRating RecipeId="@_recipe.Id"
                    Rating="@_recipe.AverageRating"
                    Count="@_recipe.RatingCount"
                    OnRated="HandleRating" />

        <div class="row mt-4">
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header"><strong>🥕 Ingredients</strong></div>
                    <div class="card-body">
                        <ul class="mb-0">
                            @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                            {
                                <li>@ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card">
                    <div class="card-header"><strong>📝 Steps</strong></div>
                    <div class="card-body">
                        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipeById(Id);
    }

    private void HandleRating(int stars)
    {
        RecipeService.AddRating(Id, stars);
        _recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe</PageTitle>

<div class="container">
    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <strong>Recipe submitted!</strong> Your recipe "<em>@_title</em>" has been added.
            <a href="/category/@_category">View it in @_category</a>.
        </div>
    }
    else
    {
        <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <div class="mb-3">
                <label class="form-label">Title</label>
                <InputText @bind-Value="_title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label class="form-label">Category</label>
                <InputSelect @bind-Value="_category" class="form-select">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in _categories)
                    {
                        <option value="@cat.Name">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label class="form-label">Ingredients (one per line)</label>
                <InputTextArea @bind-Value="_ingredients" class="form-control" rows="6"
                               placeholder="2 cups flour&#10;1 cup sugar&#10;..." />
            </div>

            <div class="mb-3">
                <label class="form-label">Steps (one per line)</label>
                <InputTextArea @bind-Value="_steps" class="form-control" rows="6"
                               placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients..." />
            </div>

            <button type="submit" class="btn btn-primary"
                    disabled="@(string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category))">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;
    private List<RecipeCategory> _categories = new();

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category)) return;

        RecipeService.AddRecipe(new Recipe
        {
            Title = _title,
            Category = _category,
            Ingredients = _ingredients,
            Steps = _steps,
            AverageRating = 0,
            RatingCount = 0
        });

        _submitted = true;
    }
}

