        <p>Recipe not found.</p>
    }
    else
    {
        <h1>@_recipe.Title</h1>

        <StarRating RecipeId="@_recipe.Id"
                    Rating="@_recipe.AverageRating"
                    Count="@_recipe.RatingCount"
                    OnRated="HandleRating" />

        <div class="row mt-4">
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header"><strong>🥕 Ingredients</strong></div>
                    <div class="card-body">
                        <ul class="mb-0">
                            @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                            {
                                <li>@ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card">
                    <div class="card-header"><strong>📝 Steps</strong></div>
                    <div class="card-body">
                        @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipeById(Id);
    }

    private void HandleRating(int stars)
    {
        RecipeService.AddRating(Id, stars);
        _recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe</PageTitle>

<div class="container">
    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <strong>Recipe submitted!</strong> Your recipe "<em>@_title</em>" has been added.
            <a href="/category/@_category">View it in @_category</a>.
        </div>
    }
    else
    {
        <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <div class="mb-3">
                <label class="form-label">Title</label>
                <InputText @bind-Value="_title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label class="form-label">Category</label>
                <InputSelect @bind-Value="_category" class="form-select">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in _categories)
                    {
                        <option value="@cat.Name">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label class="form-label">Ingredients (one per line)</label>
                <InputTextArea @bind-Value="_ingredients" class="form-control" rows="6"
                               placeholder="2 cups flour&#10;1 cup sugar&#10;..." />
            </div>

            <div class="mb-3">
                <label class="form-label">Steps (one per line)</label>
                <InputTextArea @bind-Value="_steps" class="form-control" rows="6"
                               placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients..." />
            </div>

            <button type="submit" class="btn btn-primary"
                    disabled="@(string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category))">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;
    private List<RecipeCategory> _categories = new();

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category)) return;

        RecipeService.AddRecipe(new Recipe
        {
            Title = _title,
            Category = _category,
            Ingredients = _ingredients,
            Steps = _steps,
            AverageRating = 0,
            RatingCount = 0
        });

        _submitted = true;
    }
}

